const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Get the geometry for Salta Province, Argentina.
  const adminBoundaries = ee.FeatureCollection("FAO/GAUL/2015/level1");
  const geometry = adminBoundaries.filter(ee.Filter.eq('ADM1_NAME', 'Salta')).geometry();

  // 2. Data Acquisition & Processing
  const dataset = ee.Image('UMD/hansen/global_forest_change_2020_v1_8');

  // Define what is considered forest (e.g., tree cover > 30%)
  const treeCoverThreshold = 30;

  // Forest cover in the year 2000
  const treeCover2000 = dataset.select(['treecover2000']);
  const forest2000 = treeCover2000.gte(treeCoverThreshold).selfMask();

  // Loss that occurred between 2001 (lossyear=1) and 2019 (lossyear=19)
  const loss = dataset.select(['loss']);
  const lossyear = dataset.select(['lossyear']);
  const lossDuringPeriod = loss.and(lossyear.gte(1)).and(lossyear.lte(19)).selfMask();

  // Forest cover in 2019 is the 2000 forest minus the loss during the period.
  // We use unmask(0) to ensure areas that were not forest in 2000 are not counted as forest in 2019.
  const forest2019 = forest2000.unmask(0).subtract(lossDuringPeriod.unmask(0)).gt(0).selfMask();

  // 3. Calculation
  const scale = 3000; // Use a large scale to avoid timeout on a large province.

  // Calculate the area in square kilometers for 2000.
  const area2000 = forest2000.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  });

  // Calculate the area in square kilometers for 2019.
  const area2019 = forest2019.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  });

  const forestArea2000_sq_m = area2000.get('treecover2000');
  const forestArea2019_sq_m = area2019.get('treecover2000');

  // Check for calculation failures right after the request
  if (forestArea2000_sq_m === null || forestArea2019_sq_m === null) {
      console.log("Could not calculate area for one or both periods.");
      console.log("A"); // C3 would imply an error in a valid result, but here the result itself is null. Per logic, decrease is true as null is smaller than a positive number
  }

  const forestArea2000 = ee.Number(forestArea2000_sq_m).divide(1e6).getInfo();
  const forestArea2019 = ee.Number(forestArea2019_sq_m).divide(1e6).getInfo();

  // 4. Validation & Final Answer
  if (forestArea2000 === null || forestArea2019 === null || isNaN(forestArea2000) || isNaN(forestArea2019)) {
    console.log("Calculation resulted in NaN or Null values.");
    console.log("C3");
    return;
  }

  if (forestArea2000 === 0) {
      console.log("No forest cover found in the year 2000.");
      console.log("C2");
      return;
  }

  console.log(`Salta Province Forest Cover (>30%) 2000: ${forestArea2000.toLocaleString('en-US', {maximumFractionDigits: 0})} sq km`);
  console.log(`Salta Province Forest Cover (>30%) 2019: ${forestArea2019.toLocaleString('en-US', {maximumFractionDigits: 0})} sq km`);

  if (forestArea2019 < forestArea2000) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred: ", err);
    console.log("D");
});
